payload.arguments:
{"cmd": "$d = Join-Path $env:TEMP "wsprobe_$PID"; New-Item -ItemType Directory $d | Out-Null
[IO.File]::WriteAllBytes("$d\s.txt",[byte[]][char[]]"The cat sat.`nThe cat ran!`nA dog.`n")
[IO.File]::WriteAllBytes("$d\e.txt",[byte[]]@())
[IO.File]::WriteAllBytes("$d\bad.txt",[byte[]]@(0x61,0xff))
[IO.File]::WriteAllBytes("$d\crlf.txt",[byte[]][char[]]"a b`r`nc`r`n")
function t($a){ $o="$d\o.bin";$e="$d\e.bin"; $p=Start-Process python -ArgumentList (@('-m','wordstat')+$a) -NoNewWindow -Wait -PassThru -RedirectStandardOutput $o -RedirectStandardError $e -RedirectStandardInput "$d\e.txt"; "ARGS: $a => exit $($p.ExitCode) out=$([BitConverter]::ToString([IO.File]::ReadAllBytes($o)).Length/3)B"; [Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($o)).Replace("`r","<CR>").Replace("`n","<LF>"); "ERR: "+[Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($e)).Replace("`r","<CR>").Replace("`n","<LF>") }
t @("$d\s.txt"); t @('--json','--top','2',"$d\s.txt"); t @("$d\e.txt"); t @("$d\nope.txt"); t @($d); t @("$d\bad.txt")
foreach($x in '0','-1','abc'){ t @('--top',$x,"$d\s.txt") }
t @("$d\s.txt",'--top'); t @('--bogus',"$d\s.txt"); t @(); t @('--top','+2',"$d\s.txt"); t @("$d\crlf.txt"); t @('--to','2',"$d\s.txt")
Remove-Item -Recurse -LiteralPath $d"}
